#!/usr/bin/env node
// A line number into a GENERATED file is a citation with a shelf life.
//
// ── the incident ──────────────────────────────────────────────────────────
//
// `studio-web/app/deletions/page.tsx` explains why you cannot count the
// erasure's blast radius by parsing the schema, and backs the point with a
// citation:
//
//     a `create table` clause is not the last word on a foreign key.
//     supabase/setup.sql:28188-28206 DROPS and RECREATES three of them.
//
// The claim is true. The citation is not. Those `alter table … drop constraint
// … add constraint … on delete set null` statements are at 28319-28321 today.
// Lines 28188-28206 now hold a block of commentary about month-end
// reconciliation — related subject, entirely different statements. Nothing
// moved on purpose: `supabase/setup.sql` is GENERATED by
// `scripts/build-supabase-setup.mjs`, which concatenates `supabase/parts/*.sql`
// in dependency order. A part ABOVE part 184 grew, the bundle was rebuilt, and
// every line number into the file below that point shifted. The citation was
// correct when it was written and became false without anybody touching it or
// the thing it points at.
//
// This is not a hazard that can be edited away one citation at a time. Any
// line number into a generated bundle is stale the moment a part above it
// changes, which on this repo is most days. It is the citation FORM that is
// wrong, not the number in it.
//
// ── what the existing gates could see ─────────────────────────────────────
//
// `check:doc-paths` verifies that a cited PATH exists, and that a `file.ts:123`
// names a line the file HAS. Both hold here: `supabase/setup.sql` exists and is
// 57,000 lines long, so line 28188 exists. Its own header says so in as many
// words — "`:N` here means 'not obviously impossible', not 'checked'" — and it
// is right to: whether a line still says what a document claims is not
// expressible, and a gate that failed on drift would fire on every commit.
//
// It also walks `docs/**/*.md` only. Both citations this gate found are in
// source files, so nothing was looking at either of them.
//
// ── what IS decidable ─────────────────────────────────────────────────────
//
// Not "has this line drifted" — that needs to know what the citation meant.
// But "is this a line number into a file that is REBUILT from other files" is
// a property of the target, and it is stamped on the target's own first lines:
//
//     -- GENERATED from supabase/parts/*.sql by scripts/build-supabase-setup.mjs.
//     -- Do not hand-edit — edit the part and rebuild.
//
// So the rule is about the FORM of the citation, and it can be applied without
// any judgement about the sentence beside it:
//
//     A citation may not name a line, or a range of lines, in a generated file.
//
// The fix is always available and always better. Every one of these statements
// lives in a part file that nothing regenerates, and most of them have a name
// that no rebuild can move: `gym_invoices_member_id_fkey` is findable for as
// long as it exists, which is the property a citation wants. Lane 99 removed
// the equivalent citations from `web/studio.html` and
// `supabase/parts/41-account-deletion.sql` in favour of constraint names for
// exactly this reason.
//
// ── what this deliberately does NOT check ─────────────────────────────────
//
//   · A LINE NUMBER INTO A HAND-WRITTEN FILE. `src/lib/foo.ts:42` drifts too,
//     and this says nothing about it, because there is no mechanical way to
//     tell a drifted line from a current one and `check:doc-paths` has already
//     written down why guessing is worse than silence. The distinction this
//     gate draws is narrower and sound: a generated file is rebuilt by a
//     script, on a schedule nobody controls, from inputs the citation does not
//     name — so the citation is not merely AT RISK of going stale, it has no
//     mechanism that could keep it fresh.
//
//   · WHETHER THE CITATION IS TRUE. As everywhere else in this repo's gates.
//     One of the two citations below is still correct today by luck
//     (`supabase/setup.sql line 2494` does land on the policy it names). It is
//     still in the list, because the next rebuild is what decides that, not
//     this run.
//
//   · A PATH IT CANNOT RESOLVE. If the cited path is not a file on disk this
//     stays quiet — that is `check:doc-paths`'s job for `docs/`, and guessing
//     at what a half-path meant is how a gate starts false-alarming.
//
//   · A GENERATED FILE'S OWN CONTENTS. `supabase/setup.sql` is not scanned,
//     because a citation inside it came from a part and the part is where it
//     has to be fixed.

import { readdirSync, statSync, readFileSync, existsSync } from 'node:fs';
import { join, relative } from 'node:path';

const ROOT = new URL('..', import.meta.url).pathname;

/**
 * The citations that existed when this gate was written, and could not be
 * cleared in the same change because they are in other lanes' files.
 *
 * A RATCHET, not an exemption. An entry may be removed and may never be added,
 * and an entry that no longer matches anything is itself a failure — otherwise
 * the list quietly becomes a licence. Clear one by replacing the line number
 * with a name that does not move: a constraint name, a policy name, a function
 * name, or the part file the statement actually lives in.
 */
const KNOWN = new Map([
  ['studio-web/app/deletions/page.tsx', {
    cites: ['supabase/setup.sql:28188-28206'],
    why: 'ALREADY STALE, measured 14 Sep 2026: the `alter table … drop constraint … gym_invoices_member_id_fkey` statements it means are at 28319-28321, and 28188-28206 now hold commentary about month-end reconciliation. Replace with the three constraint names — gym_invoices_member_id_fkey, gym_payments_member_id_fkey, memberships_member_id_fkey — and the part that carries them, supabase/parts/184-an-erasure-that-does-not-unbalance-the-books.sql. Lane 82 owns the file.',
  }],
  ['src/lib/coachKit.ts', {
    cites: ['supabase/setup.sql line 2494'],
    why: 'Still lands on `create policy gym_equipment_staff_r on gym_equipment` today, checked 14 Sep 2026 — and that is luck, not a property of the citation. Replace with the policy name and supabase/parts/34, both of which a rebuild cannot move.',
  }],
]);

const ROOTS = ['app', 'src', 'studio-web', 'scripts', 'web', 'docs', 'supabase/parts'];
const EXT = /\.(tsx?|jsx?|mjs|cjs|sql|html|md)$/;
const SKIP = /node_modules|[\\/](\.next|dist|build|\.expo|\.preflight-export|ios|android)[\\/]/;

/** `path/to/file.ext:123`, `path/to/file.ext:123-456`, `path/to/file.ext line 123`. */
const CITATION = /\b((?:[\w.@-]+\/)+[\w.-]+\.[a-z]{1,5})(?::(\d+)(?:-(\d+))?|\s+lines?\s+(\d+))/gi;

/**
 * What counts as generated, and why it is read two ways.
 *
 * The obvious detector — "does the header say GENERATED" — is one grep away
 * from being wrong in both directions. A first attempt matched five files that
 * merely TALK about generation: `scripts/build-supabase-setup.mjs` ("setup.sql
 * is generated. Edit the part, never the bundle."), `src/lib/meals.ts` ("Meals
 * are generated by combining components"), and this file itself. Excluding
 * those from the scan silently stops checking the citations inside them, which
 * is the failure mode a gate must not have.
 *
 * So the set is parsed out of the GENERATORS, which is this repo's own rule for
 * what a check may do: every `scripts/build-*.mjs` declares the path it writes,
 * and that declaration is the authority on what is rebuilt. The header form is
 * kept as a second, strict reading — GENERATED as the first word of a header
 * line — so a file written by something other than a `build-*` script still
 * counts. Prose about generation does not start a line with the word.
 */
const GENERATED_HEADER = /^[^\w\n]{0,8}GENERATED\s+(?:from|by)\b/m;
const OUT_DECL = /\b(?:OUT|OUT_SQL|OUT_FILE|OUTPUT|TARGET|DEST)[A-Z_]*\s*=\s*(?:join\(\s*ROOT\s*,\s*)?'([^']+)'/g;

/** The paths `scripts/build-*.mjs` declare that they write. */
function declaredOutputs() {
  const out = new Set();
  let names;
  try { names = readdirSync(join(ROOT, 'scripts')); } catch { return out; }
  for (const n of names) {
    if (!/^build-.*\.mjs$/.test(n)) continue;
    const raw = readFileSync(join(ROOT, 'scripts', n), 'utf8');
    for (const m of raw.matchAll(OUT_DECL)) {
      const p = m[1];
      if (!/\.[a-z]{1,5}$/i.test(p)) continue;          // a directory, not a file
      if (existsSync(join(ROOT, p))) out.add(p);
    }
  }
  return out;
}

const DECLARED = declaredOutputs();

const problems = [];
const fatal = [];
const generated = new Map();

function isGenerated(rel) {
  if (generated.has(rel)) return generated.get(rel);
  let v = DECLARED.has(rel);
  if (!v) {
    try {
      // The stamp is a header, by convention and by necessity — a reader has
      // to meet it before they edit. Twelve lines is generous for one.
      v = GENERATED_HEADER.test(readFileSync(join(ROOT, rel), 'utf8').split('\n', 12).join('\n'));
    } catch { v = false; }
  }
  generated.set(rel, v);
  return v;
}

function walk(dir, out = []) {
  let entries;
  try { entries = readdirSync(dir, { withFileTypes: true }); } catch { return out; }
  for (const e of entries) {
    const p = join(dir, e.name);
    if (SKIP.test(p)) continue;
    if (e.isDirectory()) walk(p, out);
    else if (EXT.test(e.name)) out.push(p);
  }
  return out;
}

const files = ROOTS.flatMap((r) => walk(join(ROOT, r))).map((p) => relative(ROOT, p)).sort();
if (files.length < 200) {
  fatal.push(`only ${files.length} files found under ${ROOTS.join(', ')}, which cannot be right — this repo holds thousands. A gate that has been pointed at the wrong tree prints the same "ok" as a clean one.`);
}

// The empty-set guard's other half: if nothing in this repo is stamped
// GENERATED any more, this gate has nothing to protect and is quietly passing
// on a rule it can no longer apply.
let generatedSeen = 0;
let citationsSeen = 0;

// This file is not scanned, and the reason is not convenience. A gate that
// documents the defect it catches has to QUOTE the defect — the incident above
// reproduces the citation verbatim, and the ratchet below stores each offending
// string exactly so it can be matched. Scanning itself would fail on its own
// evidence and the only way out would be to stop writing the evidence down.
// Nothing else is exempt; everything else uses the marker.
const SELF = 'scripts/check-generated-citations.mjs';

for (const rel of files) {
  if (rel === SELF) continue;
  if (isGenerated(rel)) { generatedSeen += 1; continue; }
  const raw = readFileSync(join(ROOT, rel), 'utf8');
  const lines = raw.split('\n');

  for (const m of raw.matchAll(CITATION)) {
    const target = m[1];
    if (!existsSync(join(ROOT, target))) continue;
    citationsSeen += 1;
    if (!isGenerated(target)) continue;
    const line = raw.slice(0, m.index).split('\n').length;
    if (/generated-citation-ok:/.test(lines.slice(Math.max(0, line - 3), line).join('\n'))) continue;
    problems.push({ file: rel, line, cite: m[0].trim(), target });
  }
}

if (generatedSeen === 0) {
  fatal.push(`nothing under the scanned roots reads as generated: ${DECLARED.size} output path${DECLARED.size === 1 ? '' : 's'} declared by scripts/build-*.mjs and no GENERATED header found. supabase/setup.sql is generated — or was — so either the declarations moved out from under OUT_DECL, or nothing here is rebuilt any more and this gate should be deleted rather than left printing "ok".`);
}
if (citationsSeen < 10) {
  fatal.push(`check-generated-citations resolved only ${citationsSeen} path:line citations across the repo. There are far more than that; the CITATION pattern has stopped matching the way this repo writes them.`);
}

if (fatal.length) {
  console.error('\ncheck-generated-citations cannot run honestly:\n');
  for (const f of fatal) console.error(`  · ${f}\n`);
  process.exit(1);
}

const byFile = new Map();
for (const p of problems) byFile.set(p.file, [...(byFile.get(p.file) ?? []), p]);

const fresh = [];
for (const [file, list] of byFile) {
  const known = KNOWN.get(file);
  for (const p of list) {
    if (known?.cites.includes(p.cite)) continue;
    fresh.push(p);
  }
}

// The ratchet only counts down if somebody turns it.
const stale = [];
for (const [file, known] of KNOWN) {
  const now = (byFile.get(file) ?? []).map((p) => p.cite);
  for (const cite of known.cites) {
    if (!now.includes(cite)) stale.push({ file, cite });
  }
}

if (fresh.length) {
  console.error('\nA citation names a line in a file that is rebuilt from other files:\n');
  for (const p of fresh) {
    console.error(`  ${p.file}:${p.line}`);
    console.error(`    cites  ${p.cite}`);
    console.error(`    but    ${p.target} is GENERATED. Its line numbers move whenever any input above that point grows,`);
    console.error('           so this citation is stale the next time the bundle is rebuilt, without anybody');
    console.error('           touching it or the statement it points at.\n');
  }
  console.error('Cite something a rebuild cannot move: a constraint, policy, function or table name, and');
  console.error('the part file the statement lives in. Where a line number is genuinely the only handle,');
  console.error('put `generated-citation-ok: <reason>` in the comment run directly above it — with the');
  console.error('reason, which is the part that is worth anything.\n');
  process.exit(1);
}

if (stale.length) {
  console.error('\nKNOWN is out of date — the ratchet only counts down if somebody turns it:\n');
  for (const s of stale) console.error(`  ${s.file} no longer cites ${s.cite}`);
  console.error('\nRemove it from KNOWN in scripts/check-generated-citations.mjs.\n');
  process.exit(1);
}

const owed = [...KNOWN.values()].reduce((n, k) => n + k.cites.length, 0);
console.log(`check-generated-citations — ok, ${files.length} files scanned, ${citationsSeen} path:line citations resolved, `
  + `${generatedSeen} generated file${generatedSeen === 1 ? '' : 's'} off limits to them; `
  + `${owed} citation${owed === 1 ? '' : 's'} still owed, both into supabase/setup.sql and both recorded in KNOWN.`);
